function chunkSeq(words){ const out = []; let i = 0; while(i < words.length){ const rem = words.length - i, sz = rem === 4 ? 2 : rem >= 3 ? 3 : rem; out.push(words.slice(i, i + sz)); i += sz; } return out; }
