function exportSessionsToCSV(){
const list = loadSessions();
if(list.length === 0){
alert("Henüz dışa aktarılacak kayıt yok.");
return;
}
const headers = ["Tarih","Kişi","Egzersiz","Aşama","Düzey","Süre (sn)","Hata Sayısı"];
const rows = list.map(r => [
new Date(r.t).toLocaleString("tr-TR"),
r.player,
r.exerciseLabel,
r.stageLabel,
r.tier,
(r.ms/1000).toFixed(1),
r.errors || 0
]);
const csvLines = [headers, ...rows].map(row =>
row.map(cell => `"${String(cell).replace(/"/g,'""')}"`).join(",")
);
const csvContent = "\uFEFF" + csvLines.join("\r\n");
const blob = new Blob([csvContent], {type: "text/csv;charset=utf-8;"});
const url = URL.createObjectURL(blob);
const a = document.createElement("a");
a.href = url;
a.download = `calisan-bellek-sonuclari-${new Date().toISOString().slice(0,10)}.csv`;
document.body.appendChild(a);
a.click();
document.body.removeChild(a);
URL.revokeObjectURL(url);
}

